package com.hackathon.setscan;

import org.json.*;
import org.junit.Test;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import static org.junit.Assert.*;

public class PilotIntakeTest {
    private static final long NOW=1794052800000L;
    private interface Throwing{void run()throws Exception;}
    private void rejected(Throwing action){try{action.run();fail("Invalid/unauthorized operation accepted");}catch(Exception expected){assertNotNull(expected.getMessage());}}
    private PilotIntake.Host host(){return new PilotIntake.Host("Synthetic QA demo host","host@example.test");}
    private PilotIntake.Notebook empty(){return new PilotIntake.Notebook().withHost(host());}
    private PilotIntake.Draft draft(){return new PilotIntake.Draft("Synthetic QA contact","person@example.test","","","Real short-film location scout next week","Need measured room/kit clearance before bringing a camera",PilotIntake.Authority.NOT_STATED);}
    private PilotIntake.Notebook one(){return empty().optIn(null,draft(),true,NOW);}
    @Test public void noConsentCannotCreateMarketingContact(){PilotIntake.Notebook n=empty();rejected(()->n.optIn(null,draft(),false,NOW));assertEquals(0,n.leads.size());}
    @Test public void identifiedRecipientIsRequiredBeforeOptIn(){rejected(()->new PilotIntake.Notebook().optIn(null,draft(),true,NOW));}
    @Test public void validOptInRecordsExactNoticeVersionAndDeviceTime(){PilotIntake.Lead l=one().leads.get(0);assertTrue(l.active());assertEquals(NOW,l.consentedAt);assertEquals(NOW,l.createdAt);assertEquals(PilotIntake.CONSENT_VERSION,l.consentVersion);assertEquals(PilotIntake.notice(host()),l.consentNotice);assertTrue(l.consentNotice.contains("PAID"));assertTrue(l.consentNotice.contains("NOT automatically receive"));assertEquals(PilotIntake.Authority.NOT_STATED,l.authority);}
    @Test public void persistedNotebookReopensWithAllFieldsAndConsent()throws Exception{PilotIntake.Notebook n=one(),r=PilotIntake.decode(PilotIntake.encode(n));assertEquals(n.leads.get(0).id,r.leads.get(0).id);assertEquals("person@example.test",r.leads.get(0).email);assertEquals(draft().project,r.leads.get(0).project);assertEquals(PilotIntake.notice(host()),r.leads.get(0).consentNotice);assertTrue(r.host.same(host()));}
    @Test public void editingRequiresFreshAffirmativeConsentAndKeepsRecordIdentity(){PilotIntake.Notebook n=one();String id=n.leads.get(0).id;PilotIntake.Draft d=new PilotIntake.Draft("QA edit","other@example.test","Director","QA company","Actual location project","Current measurable clearance issue",PilotIntake.Authority.CAN_APPROVE_PILOT_BUDGET);rejected(()->n.optIn(id,d,false,NOW+100));PilotIntake.Notebook r=n.optIn(id,d,true,NOW+100);assertEquals(id,r.leads.get(0).id);assertEquals(NOW,r.leads.get(0).createdAt);assertEquals(NOW+100,r.leads.get(0).consentedAt);assertEquals("person@example.test",n.leads.get(0).email);assertEquals("other@example.test",r.leads.get(0).email);}
    @Test public void budgetAuthorityIsOnlySelfReportedNotVerifiedPayment()throws Exception{PilotIntake.Notebook n=empty().optIn(null,new PilotIntake.Draft("","evaluator@example.test","","","Actual commercial shoot","Current scouting problem",PilotIntake.Authority.CAN_APPROVE_PILOT_BUDGET),true,NOW);String exported=PilotIntake.exportJson(n,NOW+1);assertTrue(exported.contains("selfReportedAuthority"));assertTrue(exported.contains("CAN_APPROVE_PILOT_BUDGET"));assertTrue(exported.contains(PilotIntake.INTEREST_ONLY));assertFalse(exported.contains("paymentConfirmed"));}
    @Test public void revocationRemovesPersonalFieldsAndBlocksExport()throws Exception{PilotIntake.Notebook n=one(),r=n.revoke(n.leads.get(0).id,NOW+100);PilotIntake.Lead l=r.leads.get(0);assertFalse(l.active());assertEquals("",l.email);assertEquals("",l.name);assertEquals("",l.project);assertEquals("",l.problem);assertEquals(PilotIntake.Authority.NOT_STATED,l.authority);assertEquals(NOW+100,l.revokedAt);String stored=PilotIntake.encode(r);assertFalse(stored.contains("person@example.test"));assertFalse(stored.contains("Synthetic QA contact"));assertFalse(stored.contains(draft().project));assertEquals(0,PilotIntake.decode(stored).activeCount());rejected(()->PilotIntake.exportJson(r,NOW+101));rejected(()->PilotIntake.exportCsv(r));}
    @Test public void revokedIdentityCannotSilentlyBeReactivated(){PilotIntake.Notebook n=one();String id=n.leads.get(0).id;PilotIntake.Notebook r=n.revoke(id,NOW+1);rejected(()->r.optIn(id,draft(),true,NOW+2));PilotIntake.Notebook fresh=r.optIn(null,draft(),true,NOW+3);assertEquals(2,fresh.leads.size());assertNotEquals(id,fresh.leads.get(1).id);assertEquals(1,fresh.activeCount());}
    @Test public void explicitDeleteRemovesRecordButDoesNotPretendToRecallCopies()throws Exception{PilotIntake.Notebook n=one();String exported=PilotIntake.exportJson(n,NOW+1);PilotIntake.Notebook deleted=n.delete(n.leads.get(0).id);assertEquals(0,deleted.leads.size());assertEquals(0,PilotIntake.decode(PilotIntake.encode(deleted)).activeCount());assertTrue(exported.contains("person@example.test"));assertEquals(1,n.activeCount());}
    @Test public void mixedExportIncludesOnlyCurrentlyConsentedContacts()throws Exception{PilotIntake.Notebook n=one();String revoked=n.leads.get(0).id;PilotIntake.Notebook r=n.revoke(revoked,NOW+1).optIn(null,new PilotIntake.Draft("Active","active@example.test","","","Real project","Real problem",PilotIntake.Authority.NOT_SURE),true,NOW+2);JSONObject json=new JSONObject(PilotIntake.exportJson(r,NOW+3));assertEquals(1,json.getJSONArray("consentedContacts").length());assertEquals("active@example.test",json.getJSONArray("consentedContacts").getJSONObject(0).getString("email"));assertFalse(json.toString().contains(revoked));String csv=PilotIntake.exportCsv(r);assertTrue(csv.contains("active@example.test"));assertFalse(csv.contains("person@example.test"));assertFalse(csv.contains(revoked));}
    @Test public void csvQuotesDelimitersAndNeutralizesFormulaPrefixes(){assertEquals("\"'=(1+1)\"",PilotIntake.csvCell("=(1+1)"));assertEquals("\"'  +SUM(A1)\"",PilotIntake.csvCell("  +SUM(A1)"));assertEquals("\"'\t@evil\"",PilotIntake.csvCell("\t@evil"));assertEquals("\"'\u00a0-1\"",PilotIntake.csvCell("\u00a0-1"));assertEquals("\"a,\"\"b\"\"\nnext\"",PilotIntake.csvCell("a,\"b\"\nnext"));}
    @Test public void csvExportProtectsRealUserProvidedFormulaText(){PilotIntake.Draft d=new PilotIntake.Draft("=HYPERLINK(\"x\")","+local@example.test","@role","-company","=project","+problem",PilotIntake.Authority.NOT_STATED);String csv=PilotIntake.exportCsv(empty().optIn(null,d,true,NOW));for(String field:new String[]{"'=HYPERLINK","'+local@example.test","'@role","'-company","'=project","'+problem"})assertTrue(csv.contains(field));}
    @Test public void invalidAndOverlongInputNeverEntersNotebook(){rejected(()->new PilotIntake.Draft("","not email","","","project","problem",PilotIntake.Authority.NOT_STATED));rejected(()->new PilotIntake.Draft("","ok@example.test","",""," ","problem",PilotIntake.Authority.NOT_STATED));rejected(()->new PilotIntake.Draft("","ok@example.test","","","x".repeat(1001),"problem",PilotIntake.Authority.NOT_STATED));rejected(()->new PilotIntake.Draft("bad\u0000name","ok@example.test","","","project","problem",PilotIntake.Authority.NOT_STATED));rejected(()->new PilotIntake.Host("","host@example.test"));rejected(()->new PilotIntake.Draft("","..x@example.test","","","project","problem",PilotIntake.Authority.NOT_STATED));}
    @Test public void optionalFieldsAreNotInvented(){PilotIntake.Lead l=one().leads.get(0);assertEquals("",l.company);assertEquals("",l.role);assertEquals(PilotIntake.Authority.NOT_STATED,l.authority);}
    @Test public void duplicateActiveAddressIsRejectedCaseInsensitively(){PilotIntake.Notebook n=one();PilotIntake.Draft d=new PilotIntake.Draft("","PERSON@EXAMPLE.TEST","","","project","problem",PilotIntake.Authority.NOT_STATED);rejected(()->n.optIn(null,d,true,NOW+1));assertEquals(1,n.activeCount());}
    @Test public void changingRecipientCannotTransferActiveConsents(){PilotIntake.Notebook n=one();PilotIntake.Host other=new PilotIntake.Host("Other host","other-host@example.test");rejected(()->n.withHost(other));PilotIntake.Notebook revoked=n.revoke(n.leads.get(0).id,NOW+1).withHost(other);assertEquals(0,revoked.activeCount());assertTrue(revoked.host.same(other));}
    @Test public void backwardsClockDoesNotFabricateRenewalOrRevocation(){PilotIntake.Notebook n=one();String id=n.leads.get(0).id;rejected(()->n.optIn(id,draft(),true,NOW-1));rejected(()->n.revoke(id,NOW-1));rejected(()->empty().optIn(null,draft(),true,0));assertTrue(PilotIntake.humanTime(NOW).contains("Europe/Tallinn"));}
    @Test public void corruptConsentStatusAndDuplicateIdsFailBeforeDataReplacement()throws Exception{PilotIntake.Notebook n=one();JSONObject r=new JSONObject(PilotIntake.encode(n));r.getJSONArray("records").getJSONObject(0).put("consentVersion","unknown");rejected(()->PilotIntake.decode(r.toString()));JSONObject bad=new JSONObject(PilotIntake.encode(n));bad.getJSONArray("records").getJSONObject(0).put("interestStatus","PAID_CUSTOMER");rejected(()->PilotIntake.decode(bad.toString()));JSONObject dup=new JSONObject(PilotIntake.encode(n));dup.getJSONArray("records").put(dup.getJSONArray("records").getJSONObject(0));rejected(()->PilotIntake.decode(dup.toString()));assertEquals(1,n.activeCount());}
    @Test public void malformedOversizedAndDeepNotebooksFailSafely(){rejected(()->PilotIntake.decode("{broken"));rejected(()->PilotIntake.decode(" ".repeat(PilotIntake.MAX_BYTES+1)));rejected(()->PilotIntake.decode("[".repeat(1000)+"]".repeat(1000)));}
    @Test public void recordLimitDoesNotSilentlyEvictContacts(){PilotIntake.Notebook n=empty();for(int i=0;i<100;i++)n=n.optIn(null,new PilotIntake.Draft("","p"+i+"@example.test","","","project","problem",PilotIntake.Authority.NOT_STATED),true,NOW+i);PilotIntake.Notebook full=n;rejected(()->full.optIn(null,draft(),true,NOW+101));assertEquals(100,full.leads.size());}
    @Test public void consentRecipientAndExactWordingCannotBeReassignedOnReopen()throws Exception{JSONObject changed=new JSONObject(PilotIntake.encode(one()));changed.getJSONObject("host").put("name","Different recipient");rejected(()->PilotIntake.decode(changed.toString()));JSONObject wording=new JSONObject(PilotIntake.encode(one()));wording.getJSONArray("records").getJSONObject(0).put("consentNotice","Generic marketing permission");rejected(()->PilotIntake.decode(wording.toString()));}
    @Test public void revokedPayloadAndFutureSchemaFailValidation()throws Exception{PilotIntake.Notebook n=one();JSONObject revoked=new JSONObject(PilotIntake.encode(n.revoke(n.leads.get(0).id,NOW+1)));revoked.getJSONArray("records").getJSONObject(0).put("email","leak@example.test");rejected(()->PilotIntake.decode(revoked.toString()));JSONObject future=new JSONObject(PilotIntake.encode(n));future.put("version",2);rejected(()->PilotIntake.decode(future.toString()));}
    @Test public void storageBoundNeverSilentlyDropsOrTruncatesRecords()throws Exception{PilotIntake.Notebook n=empty();for(int i=0;i<100;i++)n=n.optIn(null,new PilotIntake.Draft("","big"+i+"@example.test","","","p".repeat(1000),"q".repeat(1000),PilotIntake.Authority.NOT_STATED),true,NOW+i);PilotIntake.Notebook large=n;rejected(()->PilotIntake.encode(large));assertEquals(100,large.activeCount());}
    @Test public void unicodeMustRoundTripWithoutReplacement()throws Exception{PilotIntake.Draft d=new PilotIntake.Draft("Märt 🎬","qa@example.test","","","Tallinn location","Measured clearance",PilotIntake.Authority.NOT_STATED);PilotIntake.Notebook n=empty().optIn(null,d,true,NOW);assertEquals(d.name,PilotIntake.decode(PilotIntake.encode(n)).leads.get(0).name);rejected(()->new PilotIntake.Draft("bad\uD800","qa@example.test","","","project","problem",PilotIntake.Authority.NOT_STATED));}
    private SecretKey key()throws Exception{KeyGenerator g=KeyGenerator.getInstance("AES");g.init(256);return g.generateKey();}
    @Test public void encryptedNotebookRoundTripsWithoutPlaintextAtRest()throws Exception{SecretKey key=key();String plain=PilotIntake.encode(one());byte[] encrypted=PilotCipher.encrypt(plain.getBytes(StandardCharsets.UTF_8),key);assertFalse(new String(encrypted,StandardCharsets.ISO_8859_1).contains("person@example.test"));PilotIntake.Notebook restored=PilotIntake.decode(new String(PilotCipher.decrypt(encrypted,key),StandardCharsets.UTF_8));assertEquals("person@example.test",restored.leads.get(0).email);}
    @Test public void randomIVMakesRepeatedSavesDifferent()throws Exception{SecretKey k=key();byte[] p=PilotIntake.encode(one()).getBytes(StandardCharsets.UTF_8);assertFalse(Arrays.equals(PilotCipher.encrypt(p,k),PilotCipher.encrypt(p,k)));}
    @Test public void wrongKeyTamperTruncationAndOversizedCiphertextAreRejected()throws Exception{SecretKey k=key();byte[] e=PilotCipher.encrypt(PilotIntake.encode(one()).getBytes(StandardCharsets.UTF_8),k);rejected(()->PilotCipher.decrypt(e,key()));byte[] header=e.clone();header[0]^=1;rejected(()->PilotCipher.decrypt(header,k));byte[] tampered=e.clone();tampered[tampered.length-1]^=1;rejected(()->PilotCipher.decrypt(tampered,k));rejected(()->PilotCipher.decrypt(new byte[8],k));rejected(()->PilotCipher.decrypt(new byte[PilotIntake.MAX_BYTES+40],k));}
    @Test public void pilotDataDoesNotJoinRoomPlanningSerialization()throws Exception{RoomEdits room=new RoomEdits();Lighting l=new Lighting();String before=room.encode(l);PilotIntake.Notebook n=one();String pilot=PilotIntake.exportJson(n,NOW+1);assertTrue(pilot.contains("person@example.test"));assertEquals(before,room.encode(l));assertFalse(room.encode(l).contains("person@example.test"));assertFalse(room.encode(l).contains("consentNotice"));}
}
